suspend fun reconcile(command: PatientCommand): PatientCommandOutcome {
    if (!command.isStructurallyValid()) {
        return PatientCommandOutcome.Rejected(PatientCommandFailure.INVALID_COMMAND)
    }
    return try {
        if (dao.receipt(command.operationUuid) != null || dao.clinicalCommandReceipt(command.operationUuid) != null) {
            return PatientCommandOutcome.Rejected(PatientCommandFailure.DUPLICATE_OPERATION_MISMATCH)
        }
        val receipt = dao.patientCommandReceipt(command.operationUuid)
            ?: return PatientCommandOutcome.Rejected(PatientCommandFailure.CONFIRMED_NOT_SAVED)
        receipt.replay(command)
    } catch (_: SQLiteException) {
        PatientCommandOutcome.Ambiguous
    } catch (failure: Throwable) {
        if (failure is CancellationException) throw failure
        PatientCommandOutcome.Ambiguous
    }
}

suspend fun execute(command: ClinicalCommand): ClinicalCommandOutcome {
    if (!command.isStructurallyValid()) {
        return ClinicalCommandOutcome.Rejected(ClinicalCommandFailure.INVALID_COMMAND)
    }
    return try {
        database.withTransaction {
            if (dao.receipt(command.operationUuid) != null || dao.patientCommandReceipt(command.operationUuid) != null) {
                return@withTransaction ClinicalCommandOutcome.Rejected(
                    ClinicalCommandFailure.DUPLICATE_OPERATION_MISMATCH,
                )
            }
            val priorReceipt = dao.clinicalCommandReceipt(command.operationUuid)
            if (priorReceipt != null) return@withTransaction priorReceipt.replay(command)
            when (command) {
                is SaveDatingCommand -> saveDating(command)
                is SaveUltrasoundScanCommand -> saveUltrasoundScan(command)
                is SaveLabInvestigationCommand -> saveLabInvestigation(command)
                is SaveMedicationCommand -> saveMedication(command)
                is DeleteMedicationCommand -> deleteMedication(command)
                is RestoreMedicationCommand -> restoreMedication(command)
                is DeleteLabInvestigationCommand -> deleteLabInvestigation(command)
                is RestoreLabInvestigationCommand -> restoreLabInvestigation(command)
            }
        }
    } catch (abort: ClinicalCommandAbort) {
        ClinicalCommandOutcome.Rejected(abort.failure)
    } catch (_: SQLiteConstraintException) {
        ClinicalCommandOutcome.Rejected(ClinicalCommandFailure.RECORD_CONFLICT)
    } catch (_: SQLiteException) {
        ClinicalCommandOutcome.Ambiguous
    } catch (failure: Throwable) {
        if (failure is CancellationException) throw failure
        ClinicalCommandOutcome.Ambiguous
    }
}

suspend fun reconcile(command: ClinicalCommand): ClinicalCommandOutcome {
    if (!command.isStructurallyValid()) {
        return ClinicalCommandOutcome.Rejected(ClinicalCommandFailure.INVALID_COMMAND)
    }
    return try {
        if (dao.receipt(command.operationUuid) != null || dao.patientCommandReceipt(command.operationUuid) != null) {
            return ClinicalCommandOutcome.Rejected(ClinicalCommandFailure.DUPLICATE_OPERATION_MISMATCH)
        }
        val receipt = dao.clinicalCommandReceipt(command.operationUuid)
            ?: return ClinicalCommandOutcome.Rejected(ClinicalCommandFailure.CONFIRMED_NOT_SAVED)
        receipt.replay(command)
    } catch (_: SQLiteException) {
        ClinicalCommandOutcome.Ambiguous
    } catch (failure: Throwable) {
        if (failure is CancellationException) throw failure
        ClinicalCommandOutcome.Ambiguous
    }
}

private suspend fun savePatientProfile(command: SavePatientProfileCommand): PatientCommandOutcome {
    val excluding = command.patientId.takeIf { command.expectedPatientRevision != null }
    if (dao.caseIdCount(command.caseId, excluding) != 0) {
        return PatientCommandOutcome.Rejected(PatientCommandFailure.CASE_ID_CONFLICT)
    }
    val committedRevision = if (command.expectedPatientRevision == null) {
        if (dao.patient(command.patientId) != null) {
            return PatientCommandOutcome.Rejected(PatientCommandFailure.RECORD_CONFLICT)
        }
        dao.insertPatient(command.toEntity())
        1L
    } else {
        val patient = dao.patient(command.patientId)
            ?: return PatientCommandOutcome.Rejected(PatientCommandFailure.PATIENT_NOT_FOUND)
        patient.writeGuard(command.expectedPatientRevision)?.let {
            return PatientCommandOutcome.Rejected(it)

    val name: String,
    val dosage: String,
    val route: String,
    val frequency: String,
    val startDate: String,
    val endDate: String?,
    val status: String,
    val notes: String?,
    val isProphylaxis: Boolean,
    val isNonCompliant: Boolean = false,
    val adverseNotes: String? = null,
) : ClinicalCommand {
    override val recordKind = if (expectedMedicationRevision == null) ClinicalRecordKind.MEDICATION_CREATE else ClinicalRecordKind.MEDICATION_UPDATE
    override val recordId = medicationId

    override fun destination(): AncRoute = AncRoute.Workspace(patientId, WorkspaceSection.MEDICATIONS)
    override fun savedNotice(): SavedNotice = SavedNotice.MEDICATIONS

    override fun isStructurallyValid(): Boolean {
        if (!isValidUuid(operationUuid) || patientId.isBlank() || medicationId.isBlank() || expectedPatientRevision < 1) return false
        if (expectedMedicationRevision != null && expectedMedicationRevision < 1) return false
        if (name.isBlank() || dosage.isBlank() || frequency.isBlank()) return false
        if (route !in ClinicalVocabulary.medicationRoutes) return false
        if (status !in ClinicalVocabulary.medicationStatuses) return false
        if (!ClinicalVocabulary.isValidIsoDate(startDate) || startDate.isBlank()) return false
        if (!ClinicalVocabulary.isValidIsoDate(endDate)) return false
        return true
    }

    override fun computeFingerprint(): String = sha256(
        "MED|$operationUuid|$patientId|$expectedPatientRevision|$medicationId|$expectedMedicationRevision|$name|$dosage|$route|$frequency|$startDate|$endDate|$status|$notes|$isProphylaxis|$isNonCompliant|$adverseNotes",
    )

    companion object {
        fun prepare(state: AncState, operationUuid: String, medicationId: String): ClinicalCommandPreparation {
            val draft = state.medicationDraft
                ?: return ClinicalCommandPreparation.Rejected(setOf(ClinicalValidationError.SAVE_FAILED))
            val errors = mutableSetOf<ClinicalValidationError>()

            val name = draft.values.name.trim()
            if (name.isEmpty()) {
                errors.add(ClinicalValidationError.REQUIRED_NAME)
            }

            val dosage = draft.values.dosage.trim()
            if (dosage.isEmpty()) {
                errors.add(ClinicalValidationError.REQUIRED_DOSAGE)
            }

            val route = draft.values.route.trim().ifEmpty { "Oral" }
            if (route !in ClinicalVocabulary.medicationRoutes) {
                errors.add(ClinicalValidationError.INVALID_ROUTE)
            }

            val frequency = draft.values.frequency.trim()
            if (frequency.isEmpty()) {
                errors.add(ClinicalValidationError.REQUIRED_FREQUENCY)
            }

            val startDate = draft.values.startDate.trim()
            if (startDate.isEmpty()) {
                errors.add(ClinicalValidationError.REQUIRED_DATE)
            } else if (!ClinicalVocabulary.isValidIsoDate(startDate)) {
                errors.add(ClinicalValidationError.INVALID_DATE)
            }

            val endDate = draft.values.endDate.trim().ifEmpty { null }
            if (endDate != null && !ClinicalVocabulary.isValidIsoDate(endDate)) {
                errors.add(ClinicalValidationError.INVALID_DATE)
            }

            val status = draft.values.status.trim().ifEmpty { MEDICATION_STATUS_ACTIVE }
            if (status !in ClinicalVocabulary.medicationStatuses) {
                errors.add(ClinicalValidationError.INVALID_STATUS)
            }

            if (errors.isNotEmpty()) return ClinicalCommandPreparation.Rejected(errors)

            val command = SaveMedicationCommand(
                editorSessionId = draft.editorSessionId,
                operationUuid = operationUuid,
                patientId = draft.patientId,
                expectedPatientRevision = draft.basePatientRevision,
                medicationId = medicationId,
                expectedMedicationRevision = draft.baseMedicationRevision,
                name = name,
                dosage = dosage,
                route = route,
                frequency = frequency,
                startDate = startDate,
                endDate = endDate,
                status = status,
                notes = draft.values.notes.trim().ifEmpty { null },
                isProphylaxis = draft.values.isProphylaxis,
                isNonCompliant = draft.values.isNonCompliant,
                adverseNotes = draft.values.adverseNotes.trim().ifEmpty { null },
            )
            return ClinicalCommandPreparation.Ready(command)
        }
    }
}

private val HEX_64_REGEX = Regex("^[0-9a-f]{64}$")

internal fun canonicalMedication(record: DemoMedicationRecord): String =
    "${record.patientId}|${record.id}|${record.name}|${record.dosage}|${record.route}|${record.frequency}|${record.startDate}|${record.endDate}|${record.status}|${record.notes}|${record.isProphylaxis}|${record.isNonCompliant}|${record.adverseNotes}"

internal fun canonicalLab(record: DemoLabInvestigation): String =
    "${record.patientId}|${record.id}|${record.date}|${record.testCategory}|${record.testName}|${record.result}|${record.unit}|${record.referenceRange}|${record.isAbnormal}|${record.notes}|${record.labName}"

fun medicationContentHash(record: DemoMedicationRecord): String = sha256(canonicalMedication(record))

fun labContentHash(record: DemoLabInvestigation): String = sha256(canonicalLab(record))

data class DeleteMedicationCommand(
    override val editorSessionId: String = "",
    override val operationUuid: String,
    override val patientId: String,
    override val expectedPatientRevision: Long,
    val medicationId: String,
    val expectedMedicationRevision: Long,
    val deletedContentHash: String,
) : ClinicalCommand {
    override val recordKind = ClinicalRecordKind.MEDICATION_DELETE
    override val recordId = medicationId

    override fun destination(): AncRoute = AncRoute.Workspace(patientId, WorkspaceSection.MEDICATIONS)
    override fun savedNotice(): SavedNotice = SavedNotice.MEDICATION_DELETED

    override fun isStructurallyValid(): Boolean {
        if (!isValidUuid(operationUuid) || patientId.isBlank() || medicationId.isBlank()) return false
        if (expectedPatientRevision < 1 || expectedMedicationRevision < 1) return false
        if (!deletedContentHash.matches(HEX_64_REGEX)) return false
        return true
    }

    override fun computeFingerprint(): String = sha256(
        "MED_DEL|$operationUuid|$patientId|$expectedPatientRevision|$medicationId|$expectedMedicationRevision|$deletedContentHash",
    )
}

data class RestoreMedicationCommand(
    override val editorSessionId: String = "",
    override val operationUuid: String,
    override val patientId: String,
    override val expectedPatientRevision: Long,
    val record: DemoMedicationRecord,
    val sourceDelete: DeleteMedicationCommand,
) : ClinicalCommand {
    override val recordKind = ClinicalRecordKind.MEDICATION_RESTORE
    override val recordId: String get() = record.id

    override fun destination(): AncRoute = AncRoute.Workspace(patientId, WorkspaceSection.MEDICATIONS)
    override fun savedNotice(): SavedNotice = SavedNotice.MEDICATION_RESTORED

    override fun isStructurallyValid(): Boolean {
        if (!isValidUuid(operationUuid) || patientId.isBlank() || record.id.isBlank()) return false
        if (expectedPatientRevision < 1) return false
        if (!sourceDelete.isStructurallyValid()) return false
        return true
    }

    override fun computeFingerprint(): String = sha256(
        "MED_RES|$operationUuid|$patientId|$expectedPatientRevision|${sourceDelete.computeFingerprint()}|${canonicalMedication(record)}",
    )
}

data class DeleteLabInvestigationCommand(
    override val editorSessionId: String = "",
    override val operationUuid: String,
    override val patientId: String,
    override val expectedPatientRevision: Long,
    val labId: String,
    val expectedLabRevision: Long,
    val deletedContentHash: String,
) : ClinicalCommand {
    override val recordKind = ClinicalRecordKind.LAB_DELETE
    override val recordId = labId

    override fun destination(): AncRoute = AncRoute.Workspace(patientId, WorkspaceSection.LABORATORY)
    override fun savedNotice(): SavedNotice = SavedNotice.LAB_DELETED

    override fun isStructurallyValid(): Boolean {
        if (!isValidUuid(operationUuid) || patientId.isBlank() || labId.isBlank()) return false
        if (expectedPatientRevision < 1 || expectedLabRevision < 1) return false
        if (!deletedContentHash.matches(HEX_64_REGEX)) return false
        return true
    }

    override fun computeFingerprint(): String = sha256(
        "LAB_DEL|$operationUuid|$patientId|$expectedPatientRevision|$labId|$expectedLabRevision|$deletedContentHash",
    )
}

data class RestoreLabInvestigationCommand(
    override val editorSessionId: String = "",
    override val operationUuid: String,
    override val patientId: String,
    override val expectedPatientRevision: Long,
    val record: DemoLabInvestigation,
    val sourceDelete: DeleteLabInvestigationCommand,
) : ClinicalCommand {
    override val recordKind = ClinicalRecordKind.LAB_RESTORE
    override val recordId: String get() = record.id

    override fun destination(): AncRoute = AncRoute.Workspace(patientId, WorkspaceSection.LABORATORY)
    override fun savedNotice(): SavedNotice = SavedNotice.LAB_RESTORED

    override fun isStructurallyValid(): Boolean {
        if (!isValidUuid(operationUuid) || patientId.isBlank() || record.id.isBlank()) return false
        if (expectedPatientRevision < 1) return false
        if (!sourceDelete.isStructurallyValid()) return false
        return true
    }

    override fun computeFingerprint(): String = sha256(
        "LAB_RES|$operationUuid|$patientId|$expectedPatientRevision|${sourceDelete.computeFingerprint()}|${canonicalLab(record)}",
    )
}

private fun isValidUuid(raw: String): Boolean = try {
    UUID.fromString(raw)
    true
} catch (_: Exception) {
    false
}

private fun sha256(text: String): String = sha256Hex(text)

